Select::make('subcategory')
                                            ->label('Subcategory')
                                            ->options(function ($get) {
                                                $category = $get('category');

                                                if (! $category) {
                                                    return [];
                                                }

                                                $categoryValue = $category instanceof CbdPathwayCategory ? $category->value : $category;

                                                return collect(CbdPathwaySubcategory::cases())
                                                    ->filter(fn (CbdPathwaySubcategory $case) => str_starts_with($case->value, (string) $categoryValue.'.'))
                                                    ->mapWithKeys(fn (CbdPathwaySubcategory $case) => [$case->value => $case->getLabel()]);
                                            })->required

TextColumn::make('first_country')
                    ->label('1st Country of Introduction')
                    ->formatStateUsing(static function ($state): string {
                        if (blank($state)) {
                            return '-';
                        }

                        $countries = is_array($state) ? $state : [$state];

                        return implode(', ', array_filter($countries));
                    })->searchable

TextInput::make('doi')
            ->label('DOI')
            ->unique(ignoreRecord: true)
            ->live(onBlur: true)
            ->afterStateUpdated(function (Set $set, $state, $operation) {
                if ($operation === 'view' || empty($state)) {
                    return;
                }

                $service = app(DoiMetadataService::class);
                $metadata = $service->fetchFromCrossref($state);

                if ($metadata) {
                    $set('full_ref', $metadata['full_ref']);
                    $set('short_ref', $metadata['short_ref']);
                    $set('type', $metadata['type']->value);
                    $set('link', $metadata['link']);

                    Notification::make()
                        ->title('Metadata fetched automatically')
                        ->success()
                        ->send();
                }
            })
            ->placeholder('10.1000/182')
            ->hintIcon('heroicon-m-question-mark-circle',
                tooltip: 'Enter the DOI and click "Fetch" to automatically fill in the fields. Validation checks for duplicates upon entry.')
            ->prefixAction(
                Action::make('openDoi')
                    ->icon(TablerIcon::Link)
                    ->color('primary')
                    ->tooltip('Open DOI in new tab')
                    ->url(fn ($state) => $state ? "https://doi.org/{$state}" : null)
                    ->openUrlInNewTab()
                    ->hidden(fn ($state) => empty($state))
            )
            ->suffixActions([
                Action::make('fetchFromDoi')
                    ->icon('tabler-refresh')
                    ->tooltip('Fetch metadata')
                    ->hidden(fn ($operation) => $operation === 'view')
                    ->action(function (Set $set, $state) {
                        if (empty($state)) {
                            Notification::make()
                                ->title('Missing DOI')
                                ->warning()
                                ->send();

                            return;
                        }

                        $service = app(DoiMetadataService::class);
                        $metadata = $service->fetchFromCrossref($state);

                        if ($metadata) {
                            $set('full_ref', $metadata['full_ref']);
                            $set('short_ref', $metadata['short_ref']);
                            $set('type', $metadata['type']->value);
                            $set('link', $metadata['link']);

                            Notification::make()
                                ->title('Metadata fetched successfully')
                                ->success()
                                ->send();
                        } else {
                            Notification::make()
                                ->title('Could not find this DOI')
                                ->danger()
                                ->send();
                        }
                    }),
            ])->columnSpan

